#!/usr/bin/env bash
# Reproducible Synthea FHIR R4 generation for MedResolve (STAIR-Clinical).
# Population: 600 living patients (+ deceased generated by Synthea), Massachusetts,
# fixed population seed and clinician seed. Only the FHIR R4 exporter is enabled.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
JAVA="$ROOT/tools/jdk/jdk-21.0.13+9/bin/java"
JAR="$ROOT/tools/synthea/synthea-with-dependencies.jar"
POP="${POP:-600}"
SEED="${SEED:-20261101}"
OUT="$ROOT/data/datasets/synthea/raw/generated_p${POP}_seed${SEED}"
mkdir -p "$OUT"
cd "$OUT"
"$JAVA" -Xmx6g -jar "$JAR" \
  -p "$POP" -s "$SEED" -cs "$SEED" -r 20261101 \
  --exporter.baseDirectory "$OUT" \
  --exporter.fhir.export true \
  --exporter.fhir.transaction_bundle true \
  --exporter.hospital.fhir.export true \
  --exporter.practitioner.fhir.export true \
  --exporter.csv.export false \
  --exporter.ccda.export false \
  --exporter.text.export false \
  --exporter.years_of_history 10 \
  --generate.only_alive_patients false \
  Massachusetts 2>&1 | tee "$OUT/generation.log"
